import java.util.Arrays;

public class Drill {
    static String firstWord(String s) {
        return s.substring(0, s.indexOf(' '));
    }
    static String afterPrefix(String s, String p) {
        if (s.startsWith(p)) return s.substring(p.length());
        return s;
    }
    static boolean hasDash(String s) {
        return s.contains("-");
    }
    static boolean sameIgnoringCase(String a, String b) {
        return a.equalsIgnoreCase(b);
    }
    static boolean comesBefore(String a, String b) {
        return a.compareTo(b) < 0;
    }
    static String clean(String s) {
        return s.trim().toLowerCase();
    }
    static String dashesToSpaces(String s) {
        return s.replace("-", " ");
    }
    static String[] fields(String csv) {
        return csv.split(",");
    }
    static String[] words(String s) {
        return s.trim().split("\\s+");
    }
    static String sortLetters(String w) {
        char[] cs = w.toCharArray();
        Arrays.sort(cs);
        return new String(cs);
    }
    static int toNumber(String s) {
        return Integer.parseInt(s.trim());
    }
    static long toLong(String s) {
        return Long.parseLong(s);
    }
    static String asText(int n) {
        return String.valueOf(n);
    }
    static boolean blank(String s) {
        return s.isEmpty();
    }
    static boolean shouts(String s) {
        return s.endsWith("!");
    }
    static char lastChar(String s) {
        return s.charAt(s.length() - 1);
    }
    static String tail(String s) {
        @@BLANK@@
    }
    static int where(String s, String t) {
        return s.indexOf(t);
    }
    static String loud(String s) {
        return s.toUpperCase();
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(firstWord("hello world"), "hello");
        check(afterPrefix("prefix-key", "prefix-"), "key");
        check(hasDash("a-b"), true);
        check(sameIgnoringCase("Ab", "aB"), true);
        check(comesBefore("apple", "banana"), true);
        check(clean("  HeLLo "), "hello");
        check(dashesToSpaces("a-b-c"), "a b c");
        check(Arrays.toString(fields("a,b,c")), "[a, b, c]");
        check(Arrays.toString(words("  x  y z ")), "[x, y, z]");
        check(sortLetters("dcba"), "abcd");
        check(toNumber(" 42 "), 42);
        check(toLong("7000000000"), 7000000000L);
        check(asText(12), "12");
        check(blank(""), true);
        check(shouts("hey!"), true);
        check(lastChar("abc"), 'c');
        check(tail("abcdef"), "cdef");
        check(where("hello", "ll"), 2);
        check(loud("abc"), "ABC");
        done();
    }
}
